const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim();

const arrayMultiply = arr => {
    let res = 1;
    arr.forEach(i => { res *= i; });
    return res;
};

let n = input;
const nLength = n.length;

if (nLength === 1) {
    process.stdout.write(n);
    process.exit(0);
}

if (n.slice(1) === '9'.repeat(nLength - 1)) {
    process.stdout.write(String(arrayMultiply(n.split('').map(Number))));
    process.exit(0);
}

let nArr = n.split('').map(Number);
let maxVal = arrayMultiply(nArr);

for (let i = 0; i < nLength - 1; i++) {
    let arr = nArr.slice();
    arr[i] = arr[i] - 1;
    for (let j = i + 1; j < nLength; j++) {
        arr[j] = 9;
    }
    for (let j = nLength - 1; j > 0; j--) {
        if (arr[j] === 0 || arr[j] === -1) {
            arr[j] = 9;
            arr[j - 1]--;
        }
    }
    if (arr[0] === 0) {
        arr.shift();
    }
    maxVal = Math.max(maxVal, arrayMultiply(arr));
}

process.stdout.write(String(maxVal));

